async function extractDOCXText(file){const bytes=new Uint8Array(await file.arrayBuffer()),view=new DataView(bytes.buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65558);i--)if(view.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw new Error('无法读取 Word 文档');let offset=view.getUint32(end+16,true),count=view.getUint16(end+10,true),xml='';for(let i=0;i<count;i++){if(view.getUint32(offset,true)!==0x02014b50)break;const method=view.getUint16(offset+10,true),compressedSize=view.getUint32(offset+20,true),nameLength=view.getUint16(offset+28,true),extraLength=view.getUint16(offset+30,true),commentLength=view.getUint16(offset+32,true),localOffset=view.getUint32(offset+42,true),name=new TextDecoder().decode(bytes.slice(offset+46,offset+46+nameLength));if(name==='word/document.xml'){const localNameLength=view.getUint16(localOffset+26,true),localExtraLength=view.getUint16(localOffset+28,true),start=localOffset+30+localNameLength+localExtraLength,compressed=bytes.slice(start,start+compressedSize);if(method===0)xml=new TextDecoder().decode(compressed);else if(method===8){const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));xml=await new Response(stream).text()}break}offset+=46+nameLength+extraLength+commentLength}if(!xml)throw new Error('Word 文档中没有找到正文');const doc=new DOMParser().parseFromString(xml,'application/xml');return [...doc.getElementsByTagNameNS('*','p')].map(p=>[...p.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')).filter(Boolean).join('\n')}
async function extractPDFText(file){if(typeof pdfjsLib==='undefined')throw new Error('PDF 解析组件未加载，请检查网络后刷新页面重试');const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;const parts=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),content=await page.getTextContent();parts.push(content.items.map(item=>item.str).join(' '))}const text=parts.join('\n').replace(/[ \t]+\n/g,'\n').trim();if(!text)throw new Error('未能从 PDF 中提取文字，可能是扫描件，请改用 Word 或 TXT 简历');return text}
