    const stage=d.get('stage'),hasInterview=stage!=='简历筛选',mode=d.get('interviewMode'),info=(d.get('interviewInfo')||'').trim();
    const rounds=hasInterview?[{name:stage,date:d.get('interviewDate')||'',time:d.get('interviewTime')||'',place:mode==='onsite'?info:'线上面试',url:mode==='online'?info:'',feedback:'',result:''}]:[];
