  stageInput.addEventListener('change',syncInterviewFields);stageInput.addEventListener('input',syncInterviewFields);syncInterviewFields();
  modeInput.onchange=()=>{const online=modeInput.value==='online';infoLabel.textContent='具体信息';infoInput.type=online?'url':'text';infoInput.placeholder=online?'粘贴线上面试会议邀请链接':'粘贴公司地址'};
